questions.solution:
const ORDER = /^ORD-(?<year>\d{4})-(?<seq>\d{6})-(?<branch>LAG|ABJ|PHC)$/;

function parseOrderCode(code) {
  const match = ORDER.exec(code);
  if (!match) return null;
  const { year, seq, branch } = match.groups;
  return { year: Number(year), seq: Number(seq), branch };
}

console.log(parseOrderCode("ORD-2026-000123-LAG"));
console.log(parseOrderCode("ORD-2026-123-LAG"), parseOrderCode("ORD-2026-000123-KAN"));

