const NG = /^(?:\+234|234|0)([789][01]\d{8})$/;

function normalizePhone(input) {
  if (typeof input !== "string" || input.length > 32) return null;
  const match = NG.exec(input.replace(/[\s.\-()]/g, ""));
  return match ? `+234${match[1]}` : null;
}

console.log(["0803 123 4567", "+234 (906) 111-2222", "234.703.123.4567", "01 234 5678", "0".repeat(100)].map(normalizePhone));

