const PAIR = /(?<key>[a-z]+)=(?:"(?<quoted>[^"]*)"|(?<plain>\S+))/g;

function parsePairs(text) {
  const fields = {};
  for (const { groups } of text.matchAll(PAIR)) fields[groups.key] = groups.quoted ?? groups.plain;
  return fields;
}

console.log(parsePairs('order=ORD-1002 reason="card declined" ms=2210'));

