questions.solution:
function maskPhones(text) {
  return text.replace(/(?:\+234|\b0)[789][01]\d{8}\b/g, (phone) => "*".repeat(phone.length - 4) + phone.slice(-4));
}

console.log(maskPhones("Call 08031234567 or +2349061112222, order ORD-2026-000123-LAG"));

