function highlight(text, term) {
  return text.replace(new RegExp(RegExp.escape(term), "giu"), (match) => `[${match}]`);
}

console.log(highlight("C++ and c++ books", "c++"));
console.log(highlight("Rice (Bulk), rice", "(bulk)"));

